use std::f64::consts::PI;

#[derive(Clone, Debug)]
struct Node {
    i: usize,
    x: f64,
    y: f64,
    prev: usize,
    next: usize,
    removed: bool,
}

fn signed_area(data: &[(f64, f64)]) -> f64 {
    let mut sum = 0.0;
    let n = data.len();
    let mut j = n - 1;
    for i in 0..n {
        sum += (data[j].0 - data[i].0) * (data[i].1 + data[j].1);
        j = i;
    }
    sum
}

fn area(a: &Node, b: &Node, c: &Node) -> f64 {
    (b.y - a.y) * (c.x - b.x) - (b.x - a.x) * (c.y - b.y)
}

fn equals(a: &Node, b: &Node) -> bool { a.x == b.x && a.y == b.y }

fn point_in_triangle(ax: f64, ay: f64, bx: f64, by: f64, cx: f64, cy: f64, px: f64, py: f64) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0 &&
    (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0 &&
    (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

fn remove_node(nodes: &mut [Node], p: usize) {
    let prev = nodes[p].prev;
    let next = nodes[p].next;
    nodes[prev].next = next;
    nodes[next].prev = prev;
    nodes[p].removed = true;
}

fn filter_points(nodes: &mut [Node], mut start: usize) -> Option<usize> {
    if nodes[start].removed { return None; }
    let mut p = start;
    loop {
        let next = nodes[p].next;
        if equals(&nodes[p], &nodes[next]) || area(&nodes[nodes[p].prev], &nodes[p], &nodes[next]) == 0.0 {
            if p == next { return None; }
            remove_node(nodes, p);
            p = nodes[next].prev;
            start = p;
            if p == nodes[p].next { return None; }
        } else {
            p = next;
        }
        if p == start { break; }
    }
    Some(start)
}

fn is_ear(nodes: &[Node], ear: usize) -> bool {
    let a = &nodes[nodes[ear].prev];
    let b = &nodes[ear];
    let c = &nodes[nodes[ear].next];
    if area(a, b, c) >= 0.0 { return false; }
    let mut p = nodes[ear].next;
    p = nodes[p].next;
    while p != nodes[ear].prev {
        if point_in_triangle(a.x, a.y, b.x, b.y, c.x, c.y, nodes[p].x, nodes[p].y) &&
            area(&nodes[nodes[p].prev], &nodes[p], &nodes[nodes[p].next]) >= 0.0 {
            return false;
        }
        p = nodes[p].next;
    }
    true
}

fn earcut_linked(nodes: &mut [Node], ear: usize, triangles: &mut Vec<usize>) {
    let mut ear = ear;
    let mut stop = ear;
    while nodes[ear].prev != nodes[ear].next {
        let prev = nodes[ear].prev;
        let next = nodes[ear].next;
        if is_ear(nodes, ear) {
            triangles.push(nodes[prev].i);
            triangles.push(nodes[ear].i);
            triangles.push(nodes[next].i);
            remove_node(nodes, ear);
            ear = nodes[next].next;
            stop = ear;
            continue;
        }
        ear = next;
        if ear == stop {
            if let Some(filtered) = filter_points(nodes, ear) {
                if filtered != ear {
                    earcut_linked(nodes, filtered, triangles);
                }
            }
            return;
        }
    }
}

fn triangulate(n: i32) -> Vec<usize> {
    let mut pts = Vec::new();
    for i in 0..(n * 2) {
        let t = i as f64 / (n * 2) as f64;
        let angle = 4.0 * PI * t;
        pts.push((t * angle.cos(), t * angle.sin()));
    }
    if pts.len() < 3 { return Vec::new(); }
    let clockwise = true;
    let sa = signed_area(&pts);
    let order: Vec<usize> = if clockwise == (sa > 0.0) {
        (0..pts.len()).collect()
    } else {
        (0..pts.len()).rev().collect()
    };
    let m = order.len();
    let mut nodes = Vec::new();
    for &idx in &order {
        nodes.push(Node { i: idx, x: pts[idx].0, y: pts[idx].1, prev: 0, next: 0, removed: false });
    }
    for i in 0..m {
        nodes[i].prev = (i + m - 1) % m;
        nodes[i].next = (i + 1) % m;
    }
    let mut triangles = Vec::new();
    earcut_linked(&mut nodes, m - 1, &mut triangles);
    triangles
}

fn main() {
    for n in 0..=12 {
        let out = triangulate(n);
        print!("n={}: ", n);
        for v in out { print!("{} ", v); }
        println!();
    }
}
