use std::f64::consts::PI;

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Point {
    pub x: f64,
    pub y: f64,
}

pub type Ring = Vec<Point>;
pub type Polygon = Vec<Ring>;

pub fn build_spiral_polygon(n: i32) -> Polygon {
    let mut polygon = Vec::with_capacity(1);
    let mut spiral = Vec::new();
    let point_count = n.saturating_mul(2);

    if point_count > 0 {
        spiral.reserve(point_count as usize);

        for i in 0..point_count {
            let t = f64::from(i) / f64::from(point_count);
            let radius = t;
            let angle = 4.0 * PI * t;
            spiral.push(Point {
                x: radius * angle.cos(),
                y: radius * angle.sin(),
            });
        }
    }

    polygon.push(spiral);
    polygon
}

pub fn ring_signed_area(ring: &[Point]) -> f64 {
    if ring.is_empty() {
        return 0.0;
    }

    let mut sum = 0.0;
    let mut previous = ring.len() - 1;

    for current in 0..ring.len() {
        sum += (ring[previous].x - ring[current].x) * (ring[current].y + ring[previous].y);
        previous = current;
    }

    sum
}

pub fn triangle_area(a: Point, b: Point, c: Point) -> f64 {
    (b.y - a.y) * (c.x - b.x) - (b.x - a.x) * (c.y - b.y)
}

pub fn point_in_triangle(a: Point, b: Point, c: Point, p: Point) -> bool {
    (c.x - p.x) * (a.y - p.y) - (a.x - p.x) * (c.y - p.y) >= 0.0
        && (a.x - p.x) * (b.y - p.y) - (b.x - p.x) * (a.y - p.y) >= 0.0
        && (b.x - p.x) * (c.y - p.y) - (c.x - p.x) * (b.y - p.y) >= 0.0
}

