use crate::geometry::{point_in_triangle, Polygon};
use crate::linked_list::{
    build_clockwise_ring, filter_points, remove_node, triangle_area_at, Node,
};

pub fn triangulate(polygon: &Polygon) -> Vec<u32> {
    let Some(outer_ring) = polygon.first() else {
        return Vec::new();
    };

    if outer_ring.len() < 3 {
        return Vec::new();
    }

    let Some((mut nodes, start)) = build_clockwise_ring(outer_ring) else {
        return Vec::new();
    };

    let mut triangles = Vec::with_capacity((outer_ring.len().saturating_sub(2)) * 3);
    earcut_linked(&mut nodes, start, &mut triangles);
    triangles
}

fn earcut_linked(nodes: &mut [Node], start: usize, triangles: &mut Vec<u32>) {
    let mut ear = start;
    let mut stop = start;

    while nodes[ear].prev != nodes[ear].next {
        let prev = nodes[ear].prev;
        let next = nodes[ear].next;

        if is_ear(nodes, ear) {
            triangles.push(nodes[prev].vertex_index);
            triangles.push(nodes[ear].vertex_index);
            triangles.push(nodes[next].vertex_index);

            remove_node(nodes, ear);
            ear = nodes[next].next;
            stop = ear;
            continue;
        }

        ear = next;
        if ear == stop {
            if let Some(filtered) = filter_points(nodes, ear) {
                if filtered != ear {
                    earcut_linked(nodes, filtered, triangles);
                }
            }
            return;
        }
    }
}

fn is_ear(nodes: &[Node], ear: usize) -> bool {
    let prev = nodes[ear].prev;
    let next = nodes[ear].next;

    if triangle_area_at(nodes, prev, ear, next) >= 0.0 {
        return false;
    }

    let mut point = nodes[next].next;
    while point != prev {
        if point_in_triangle(
            nodes[prev].point,
            nodes[ear].point,
            nodes[next].point,
            nodes[point].point,
        ) && triangle_area_at(nodes, nodes[point].prev, point, nodes[point].next) >= 0.0
        {
            return false;
        }

        point = nodes[point].next;
    }

    true
}

